"""Clinical formulas for vitals-calc.

All functions raise InvalidPhysiology for physiologically impossible inputs
(non-positive values where positivity is required, or dbp >= sbp).
"""

import math


class InvalidPhysiology(ValueError):
    """Raised when inputs describe an impossible clinical scenario."""


def validate_positive(**values: float) -> None:
    """Ensure every named value is strictly positive."""
    for name, value in values.items():
        if value <= 0:
            raise InvalidPhysiology(f"{name} must be positive, got {value}")


def bmi(weight_kg: float, height_cm: float) -> float:
    """Body Mass Index: weight(kg) / height(m)^2."""
    validate_positive(weight_kg=weight_kg, height_cm=height_cm)
    return weight_kg / (height_cm / 100.0) ** 2


def bsa_mosteller(weight_kg: float, height_cm: float) -> float:
    """Body Surface Area via the Mosteller formula: sqrt(h * w / 3600)."""
    validate_positive(weight_kg=weight_kg, height_cm=height_cm)
    return math.sqrt(height_cm * weight_kg / 3600.0)


def bsa_du_bois(weight_kg: float, height_cm: float) -> float:
    """Body Surface Area via the Du Bois formula: 0.007184 * h^0.725 * w^0.425."""
    validate_positive(weight_kg=weight_kg, height_cm=height_cm)
    return 0.007184 * height_cm**0.725 * weight_kg**0.425


BSA_METHODS = {
    "mosteller": bsa_mosteller,
    "du_bois": bsa_du_bois,
}


def map_pressure(sbp: float, dbp: float) -> float:
    """Mean Arterial Pressure: DBP + (SBP - DBP) / 3. Requires dbp < sbp."""
    validate_positive(sbp=sbp, dbp=dbp)
    if dbp >= sbp:
        raise InvalidPhysiology(
            f"invalid physiology: diastolic ({dbp}) must be less than systolic ({sbp})"
        )
    return dbp + (sbp - dbp) / 3.0

