"""vitals-calc: educational clinical-math command line toolkit."""

import argparse
import sys

from .formulas import BSA_METHODS, InvalidPhysiology

PROG = "vitals-calc"


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog=PROG,
        description="Educational clinical calculations (not for real medical use).",
    )
    sub = parser.add_subparsers(dest="command", required=True)

    p_bmi = sub.add_parser("bmi", help="Body Mass Index")
    p_bmi.add_argument("--weight-kg", type=float, required=True)
    p_bmi.add_argument("--height-cm", type=float, required=True)

    p_bsa = sub.add_parser("bsa", help="Body Surface Area")
    p_bsa.add_argument("--weight-kg", type=float, required=True)
    p_bsa.add_argument("--height-cm", type=float, required=True)
    p_bsa.add_argument(
        "--method",
        choices=sorted(BSA_METHODS),
        default="mosteller",
    )

    p_map = sub.add_parser("map", help="Mean Arterial Pressure")
    p_map.add_argument("--sbp", type=float, required=True)
    p_map.add_argument("--dbp", type=float, required=True)

    return parser


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)

    try:
        if args.command == "bmi":
            result = f"{args.weight_kg and 0 + _bmi(args):.2f}"
        elif args.command == "bsa":
            result = f"{_bsa(args):.2f}"
        else:
            result = f"{_map(args):.1f}"
    except InvalidPhysiology as exc:
        print(str(exc), file=sys.stderr)
        return 2

    print(result)
    return 0


def _bmi(args: argparse.Namespace) -> float:
    from .formulas import bmi

    return bmi(args.weight_kg, args.height_cm)


def _bsa(args: argparse.Namespace) -> float:
    return BSA_METHODS[args.method](args.weight_kg, args.height_cm)


def _map(args: argparse.Namespace) -> float:
    from .formulas import map_pressure

    return map_pressure(args.sbp, args.dbp)


if __name__ == "__main__":
    sys.exit(main())

